	\toprule
	Partitions         & Running words \\ \midrule
	Train ($n$-gram)   &         1.6 B \\
	Train (neural LMs) &         100 M \\
	Dev                &         100 K \\
	Test               &           5 M \\ \bottomrule
\end{tabular}
}
\caption{Statistics of our corpus.\label{tab:corpus_stat}}
\end{table}

